#[test]
fn grasp_of_phantoms_puts_creature_on_top_of_library() {
    let reg = registry();
    let mut state = game_at_step(Step::PrecombatMain, P0);

    let target_creature = named_creature(&mut state, &reg, "Grizzly Bears", P1);

